import { declareWebsite } from "@common-practice/web/build/cloudflare";
import { deploymentSecrets } from "@common-practice/infrastructure/secrets";
import {
  CloudflareAccountId,
  CommitSha,
  DeploymentStage,
  PreviewCommentTarget,
  PullRequestStage,
} from "@common-practice/infrastructure/schemas";
import * as Alchemy from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as GitHub from "alchemy/GitHub";
import { Stack } from "alchemy/Stack";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Match from "effect/Match";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

/**
 * GitHub Actions supplies the pull request number, repository and the head
 * commit (`BUILD_SHA`; `GITHUB_SHA` is the synthetic merge commit). The number
 * must match the stage, so a comment can never land on another pull request.
 */
const previewCommentTarget = Effect.fn("Website.previewCommentTarget")(function* ({
  stage,
}: Readonly<{ stage: PullRequestStage }>) {
  const github = Option.fromNullishOr(yield* GitHub.GitHubEnv);
  return yield* Option.match(github, {
    // A local plan of a pull-request stage posts nothing.
    onNone: () => Effect.succeed(Option.none<PreviewCommentTarget>()),
    onSome: (actions) =>
      Effect.gen(function* () {
        yield* Schema.decodeUnknownEffect(Schema.Literal(stage))(`pr-${actions.pr}`).pipe(
          Effect.mapError((cause) => new Config.ConfigError(cause)),
        );
        const sha = yield* Config.schema(CommitSha, "BUILD_SHA");
        const target = yield* Schema.decodeUnknownEffect(PreviewCommentTarget)({
          owner: actions.owner,
          repository: actions.repository,
          pr: actions.pr,
          sha,
        }).pipe(Effect.mapError((cause) => new Config.ConfigError(cause)));
        return Option.some(target);
      }),
  });
});

export default Alchemy.Stack(
  "common-practice",
  {
    providers: Layer.mergeAll(Cloudflare.providers(), GitHub.providers()),
    state: Cloudflare.state(),
    secrets: deploymentSecrets,
  },
  Effect.gen(function* () {
    // Check the account ID from the stack's resolved Doppler/.env settings.
    yield* Config.schema(CloudflareAccountId, "CLOUDFLARE_ACCOUNT_ID");
    const stack = yield* Stack;
    const stage = yield* Schema.decodeEffect(DeploymentStage)(stack.stage).pipe(
      Effect.mapError((cause) => new Config.ConfigError(cause)),
    );
    // Only a `pr-<number>` stage can publish a pull-request comment.
    const previewComment = yield* Match.value(stage).pipe(
      Match.when(Schema.is(PullRequestStage), (prStage) =>
        previewCommentTarget({ stage: prStage }),
      ),
      Match.orElse(() => Effect.succeed(Option.none<PreviewCommentTarget>())),
    );
    return yield* declareWebsite({ stage, previewComment });
  }),
);
import * as Alchemy from "alchemy";
import * as Doppler from "alchemy/Doppler";
import * as Match from "effect/Match";

/** Native sources for every stack: .env overrides Doppler; shell settings are excluded. */
export const deploymentSecrets: readonly (
  | Doppler.DopplerSecretsProvider
  | Alchemy.Secrets.DotEnvProvider
  | Alchemy.Secrets.ProcessEnvProvider
)[] = [
  Doppler.Secrets(({ stage }) => ({
    project: "common-practice",
    config: Match.value(stage).pipe(
      Match.when("dev", () => "dev"),
      Match.when("production", () => "prd"),
      // The stack entrypoint checks the stage before declaring any resources.
      Match.orElse(() => "stg_preview"),
    ),
  })),
  Alchemy.Secrets.DotEnv(),
  Alchemy.Secrets.ProcessEnv({ disabled: true }),
];

import BackendLive, { Backend } from "@common-practice/api/worker";
import { ApiOrigin } from "@common-practice/http/schemas";
import { commonPracticePostHogBindings } from "@common-practice/infrastructure/posthog/bindings";
import { WebsiteStage } from "@common-practice/infrastructure/cloudflare/stage";
import { WebsiteZone } from "@common-practice/infrastructure/cloudflare/website-zone";
import { declareZone, websiteHosting } from "@common-practice/infrastructure/cloudflare/zone";
import { declarePreviewComment } from "@common-practice/infrastructure/github";
import {
  ApiOutput,
  ApiOutputError,
  PullRequestStage,
  WebsiteOutput,
  WebsiteOutputError,
  WorkerName,
} from "@common-practice/infrastructure/schemas";
import type {
  ApiOutputInput,
  DeploymentStage,
  PreviewCommentTarget,
  WebsiteOutputInput,
} from "@common-practice/infrastructure/schemas";
import { productionStage } from "@common-practice/infrastructure/stacks/addresses";
import { commonPracticeTraceExportProduction } from "@common-practice/infrastructure/stacks/trace-export";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Output from "alchemy/Output";
import { retain } from "alchemy/RemovalPolicy";
import * as Namespace from "alchemy/Namespace";
import * as Boolean from "effect/Boolean";
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Match from "effect/Match";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

/**
 * The native Alchemy Output resolves inside the stack's own RuntimeContext.
 * @effect-expect-leaking RuntimeContext
 */
const WebsiteApiAddress = Context.Service<"WebsiteApiAddress", Output.Output<ApiOrigin>>(
  "@common-practice/web/build/WebsiteApiAddress",
);

export const websiteBuildProps = {
  ...Option.none().pipe(websiteHosting),
  rootDir: "apps/web",
  memo: {
    include: ["**/*", "../../packages/**", "../../content/**", "../api/src/**"],
    lockfile: true,
  },
  compatibility: { date: "2026-09-22", flags: ["nodejs_compat", "enable_request_signal"] },
  // Cache and request-cancellation support are independent Cloudflare settings.
  cache: { enabled: true, crossVersionCache: false },
  dev: { host: "127.0.0.1", port: 3210, strictPort: true },
} satisfies Cloudflare.Website.ViteProps;

/**
 * Every hosted stage owns a Worker with native log and trace settings.
 * `common-practice-trace-export` owns their shared Axiom destinations.
 */
const hostedProps = Effect.fn("Website.hostedProps")(function* ({
  stage,
  apiUrl,
}: Readonly<{
  stage: DeploymentStage;
  apiUrl: Output.Output<ApiOrigin>;
}>) {
  const analytics = yield* commonPracticePostHogBindings({ stage });
  const traceExport = yield* commonPracticeTraceExportProduction;
  return {
    ...websiteBuildProps,
    // Alchemy's props resolver has no error channel. An invalid name derived
    // from the checked stage must stop the native plan rather than fall back.
    name: yield* Schema.decodeEffect(WorkerName)(`common-practice-${stage}`).pipe(Effect.orDie),
    env: {
      COMMON_PRACTICE_STAGE: stage,
      COMMON_PRACTICE_API_URL: apiUrl,
      COMMON_PRACTICE_WEBSITE_URL: Cloudflare.Worker.URL,
      BACKEND: Backend,
      ...analytics,
    },
    observability: {
      enabled: true,
      logs: {
        enabled: true,
        invocationLogs: true,
        headSamplingRate: 1,
        persist: true,
        destinations: [traceExport.logsDestinationName],
      },
      traces: {
        enabled: true,
        headSamplingRate: 1,
        persist: true,
        destinations: [traceExport.destinationName],
      },
    },
  };
});

/**
 * Every stage declares only application bindings; Cloudflare owns telemetry delivery.
 */
type WebsiteBindings = Readonly<{
  COMMON_PRACTICE_STAGE: DeploymentStage;
  COMMON_PRACTICE_API_URL: ApiOrigin;
  COMMON_PRACTICE_WEBSITE_URL: typeof Cloudflare.Worker.URL;
  BACKEND: typeof Backend;
}> &
  Effect.Success<ReturnType<typeof commonPracticePostHogBindings>>;

/**
 * Standard TanStack Website, privately connected to this stage's Effect backend.
 */
export class Website extends Cloudflare.Website.Vite<Website>()<
  WebsiteBindings,
  WebsiteStage | WebsiteZone | Context.Service.Identifier<typeof WebsiteApiAddress>
>(
  "Website",
  Effect.gen(function* () {
    const stage = yield* WebsiteStage;
    const apiUrl = yield* WebsiteApiAddress;
    return yield* Match.value(stage).pipe(
      Match.when("dev", () =>
        Effect.gen(function* () {
          const analytics = yield* commonPracticePostHogBindings({ stage });
          return {
            ...websiteBuildProps,
            name: WorkerName.make("common-practice-dev"),
            env: {
              ...analytics,
              COMMON_PRACTICE_STAGE: stage,
              COMMON_PRACTICE_API_URL: apiUrl,
              COMMON_PRACTICE_WEBSITE_URL: Cloudflare.Worker.URL,
              BACKEND: Backend,
            },
          };
        }),
      ),
      // Production overrides the shared stable-address policy with its custom domains.
      Match.when("production", () =>
        Effect.gen(function* () {
          const zone = yield* WebsiteZone;
          const hosted = yield* hostedProps({ stage, apiUrl });
          return { ...hosted, ...websiteHosting(zone) };
        }),
      ),
      Match.whenOr("preview", "integration", () => hostedProps({ stage, apiUrl })),
      Match.when(Schema.is(PullRequestStage), () => hostedProps({ stage, apiUrl })),
      Match.exhaustive,
    );
  }),
) {}

/** Worker bindings, derived from the declaration rather than written by hand. */
export type WebsiteEnv = Cloudflare.InferEnv<typeof Website>;

export const validateWebsiteOutput = Effect.fn("Website.validateOutput")(function* (
  input: typeof WebsiteOutputInput.Type,
) {
  return yield* Schema.decodeUnknownEffect(WebsiteOutput)(input).pipe(
    Effect.mapError(() => new WebsiteOutputError({ reason: "invalid-website-url" })),
  );
});

// Native mapEffect has no error channel. Invalid provider output keeps its
// named validation error as the fatal cause, as the API output check does.
export const checkedWebsiteOutput = Output.mapEffect(
  (websiteUrl: typeof WebsiteOutputInput.Type.websiteUrl) =>
    validateWebsiteOutput({ websiteUrl }).pipe(Effect.orDie),
);

/** Provider URLs become a checked origin before the browser adds a route path. */
export const validateApiOutput = Effect.fn("Website.validateApiOutput")(function* (
  input: typeof ApiOutputInput.Type,
) {
  return yield* Effect.gen(function* () {
    const output = yield* Schema.decodeUnknownEffect(ApiOutput)(input);
    const url = yield* Schema.decodeEffect(Schema.URLFromString)(output.apiUrl);
    const apiUrl = yield* Schema.decodeEffect(ApiOrigin)(url.origin);
    return { apiUrl };
  }).pipe(Effect.mapError(() => new ApiOutputError({ reason: "invalid-api-url" })));
});

/**
 * Declares the Website for one checked stage. A pull-request stage run by
 * GitHub Actions also posts its checked Preview URL on that pull request.
 */
export const declareWebsite = Effect.fn("Website.declare")(function* ({
  stage,
  previewComment,
}: Readonly<{ stage: DeploymentStage; previewComment: Option.Option<PreviewCommentTarget> }>) {
  // Production owns the live Worker; every other stage stays destroyable.
  const zone = yield* Boolean.match(stage === productionStage, {
    onFalse: () => Effect.succeedNone,
    onTrue: () => declareZone().pipe(Effect.asSome),
  });
  return yield* Effect.gen(function* () {
    const backend = yield* Backend.pipe(retain(stage === productionStage));
    const api = backend.url.pipe(
      // Native mapEffect requires a never-error Effect. An invalid deployment
      // address stops planning/apply with ApiOutputError as the fatal cause.
      Output.mapEffect((apiUrl) => validateApiOutput({ apiUrl }).pipe(Effect.orDie)),
    );
    // A distinct native namespace creates the stage-owned Website and retires
    // its former Worker Preview without changing production's Website identity.
    const website = yield* Boolean.match(stage === "production" || stage === "dev", {
      onTrue: () => Website,
      onFalse: () => Website.pipe(Namespace.push("Preview")),
    }).pipe(
      retain(stage === productionStage),
      Effect.provideService(WebsiteApiAddress, api.apiUrl),
    );
    // Recheck the current validation code when native Alchemy resolves the URL.
    const output = website.url.pipe(checkedWebsiteOutput);
    yield* Option.match(previewComment, {
      onNone: () => Effect.void,
      onSome: (target) => declarePreviewComment({ target, websiteUrl: output.websiteUrl }),
    });
    return { websiteUrl: output.websiteUrl, apiUrl: api.apiUrl };
  }).pipe(
    Effect.provide(BackendLive),
    Effect.provideService(WebsiteStage, stage),
    Effect.provideService(WebsiteZone, zone),
  );
});
