import { ContentLive, ContentSources } from "@common-practice/content/live";
import { TrainingLive, TrainingOutlines } from "@common-practice/training/live";
import { courseOutlines } from "@content/training/outlines";
import { backendAnalyticsLayer } from "@common-practice/analytics/live";
import { BackendAnalytics, AnalyticsSettings } from "@common-practice/analytics/service";
import { CaptureConfig } from "@common-practice/analytics/schemas";
import { WorkerAnalyticsConfig } from "@common-practice/infrastructure/config";
import * as Schema from "effect/Schema";
import { commonPracticePostHogBindings } from "@common-practice/infrastructure/posthog/bindings";
import { ContentUsageLive, observeApiUse } from "../../analytics.layer";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as FetchHttpClient from "effect/http/FetchHttpClient";
import { WebsiteStage } from "@common-practice/infrastructure/cloudflare/stage";
import { WebsiteZone } from "@common-practice/infrastructure/cloudflare/website-zone";
import { BackendWorkerName } from "@common-practice/infrastructure/schemas";
import { apiHosting } from "@common-practice/infrastructure/cloudflare/zone";
import { commonPracticeTraceExportProduction } from "@common-practice/infrastructure/stacks/trace-export";
import {
  IsolateIdentity,
  IsolateIdentityLive,
} from "@common-practice/infrastructure/runtime/isolate-identity";
import * as Telemetry from "alchemy/Telemetry";
import * as Logger from "effect/Logger";
import { observeHostedRequest } from "@common-practice/infrastructure/runtime/request-observation";
import { ALCHEMY_PHASE } from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Config from "effect/Config";
import * as ConfigProvider from "effect/ConfigProvider";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import type * as Scope from "effect/Scope";
import * as HttpServerRequest from "effect/http/HttpServerRequest";
import * as HttpServerResponse from "effect/http/HttpServerResponse";
import { initialiseApiApplication } from "../../application.layer";
import { PageRendererLive } from "../../og/takumi.adapter.layer";
import { bundledPages } from "../../sources";

// A lightweight binding identifier. The Website does not bundle the API implementation.
export class Backend extends Cloudflare.Worker<
  Backend,
  {
    readonly fetch: Effect.Effect<
      HttpServerResponse.HttpServerResponse,
      never,
      | HttpServerRequest.HttpServerRequest
      | Scope.Scope
      | Cloudflare.WorkerExecutionContext
      | RuntimeContext
    >;
  }
>()("Backend") {}

export default Backend.make(
  Effect.gen(function* () {
    // Alchemy replaces this flag with true in the deployed bundle. Deployment
    // services exist only in the stack; runtime startup reads actual bindings.
    if (globalThis.__ALCHEMY_RUNTIME__ === true) {
      return {};
    }
    const stage = yield* WebsiteStage;
    const analytics = yield* commonPracticePostHogBindings({ stage });
    const zone = yield* WebsiteZone;
    const base = {
      main: import.meta.url,
      name: BackendWorkerName.make(`common-practice-${stage}-backend`),
      workersDev: stage !== "production",
      dev: { host: "127.0.0.1", port: 3211, strictPort: true },
      compatibility: { date: "2026-09-22", flags: ["nodejs_compat", "enable_request_signal"] },
    };
    const domain = apiHosting(zone);
    if (stage === "dev") {
      return {
        ...base,
        env: {
          COMMON_PRACTICE_STAGE: stage,
          COMMON_PRACTICE_API_URL: Cloudflare.Worker.URL,
          ...analytics,
        },
      };
    }
    const trace = yield* commonPracticeTraceExportProduction;
    return {
      ...base,
      ...domain,
      env: {
        COMMON_PRACTICE_STAGE: stage,
        COMMON_PRACTICE_API_URL: Cloudflare.Worker.URL,
        ...analytics,
      },
      observability: {
        enabled: true,
        logs: {
          enabled: true,
          invocationLogs: true,
          headSamplingRate: 1,
          persist: true,
          destinations: [trace.logsDestinationName],
        },
        traces: {
          enabled: true,
          headSamplingRate: 1,
          persist: true,
          destinations: [trace.destinationName],
        },
      },
    };
  }),
  Effect.gen(function* () {
    // Native Workers Cache shares eligible public GETs within this deployed version.
    yield* Cloudflare.cache({ crossVersionCache: false });
    // Alchemy supplies this instance's scope during native startup. Build the
    // registered telemetry and identity there, rather than a temporary scope.
    const telemetryServices = yield* Layer.build(
      Layer.mergeAll(
        Cloudflare.Telemetry(),
        Telemetry.layer(Logger.layer([Logger.consoleJson])),
      ).pipe(Layer.provideMerge(IsolateIdentityLive)),
    );
    // Worker.URL is resolved by the provider before upload. Planning cannot
    // read that runtime binding; it only registers the native Worker shape.
    if ((yield* ALCHEMY_PHASE) === "plan") {
      return { fetch: Effect.succeed(HttpServerResponse.empty({ status: 503 })) };
    }
    const { stage, capture } = yield* WorkerAnalyticsConfig;
    const analyticsServices = yield* Layer.build(
      backendAnalyticsLayer.pipe(Layer.provide(Layer.succeed(AnalyticsSettings, capture))).pipe(
        Layer.provide(
          FetchHttpClient.layer.pipe(
            Layer.provide(
              Layer.succeed(FetchHttpClient.RequestInit, {
                credentials: "omit",
                redirect: "error",
              }),
            ),
          ),
        ),
      ),
    );
    const analytics = yield* BackendAnalytics.pipe(Effect.provideContext(analyticsServices));
    const identity = yield* IsolateIdentity.pipe(Effect.provideContext(telemetryServices));
    const contentServices = yield* Layer.build(
      TrainingLive.pipe(Layer.provide(Layer.succeed(TrainingOutlines, courseOutlines))).pipe(
        Layer.provideMerge(
          ContentUsageLive.pipe(
            Layer.provideMerge(
              ContentLive.pipe(Layer.provide(Layer.succeed(ContentSources, bundledPages))).pipe(
                Layer.provide(PageRendererLive),
              ),
            ),
          ),
        ),
      ),
    );
    const handler = yield* initialiseApiApplication.pipe(Effect.provideContext(contentServices));
    return {
      fetch: Effect.gen(function* () {
        const request = yield* HttpServerRequest.HttpServerRequest;
        const isolate = yield* identity.nextRequest;
        return yield* observeHostedRequest({
          request,
          stage,
          isolate,
          worker: "backend",
          operation: observeApiUse({
            enabled: Schema.is(CaptureConfig.cases.AnalyticsEnabled)(capture),
            operation: handler.http,
          }).pipe(Effect.provideService(BackendAnalytics, analytics)),
        });
      }),
    };
  }).pipe(
    Effect.catchTags({
      TrainingSourceError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API training outlines are invalid" }),
          ),
        ),
      IllegalArgumentError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API image cache configuration is invalid" }),
          ),
        ),
      ContentSourceError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API Markdown sources are invalid" }),
          ),
        ),
      MetadataError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API page metadata is invalid" }),
          ),
        ),
      ContentUnavailableError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API page inventory is unavailable" }),
          ),
        ),
      PageNotFoundError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API page inventory is incomplete" }),
          ),
        ),
      ImageRenderError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({
              message: "API page inventory unexpectedly requested an image",
            }),
          ),
        ),
      InvalidContentRequestError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API page inventory request is invalid" }),
          ),
        ),
      InvalidContentResponseError: () =>
        Effect.fail(
          new Config.ConfigError(
            new ConfigProvider.SourceError({ message: "API page inventory response is invalid" }),
          ),
        ),
    }),
  ),
);

