// `webMcpAtom` registers the page tools with the browser's WebMCP host; unmounting closes the
// atom's Scope, which unregisters them. Nothing here reads a browser global when the module
// loads, so importing it during server rendering is safe and registers nothing.
export const browserConfigAtom = Atom.make(Option.none<typeof WebsiteBrowserConfig.Encoded>()).pipe(
  Atom.keepAlive,
);
export const websiteConfigAtom = Atom.make<typeof WebsiteConfig.Encoded>(
  WebsiteConfig.cases.WebsiteUnavailable.make({ appearance: "device" }),
).pipe(Atom.keepAlive);
const browserAppearanceLayerAtom = Atom.make(
  browserAppearanceLayer.pipe(Layer.provide(Layer.succeed(AppearanceSettings, appearanceOptions))),
);
// Test registries can supply the same closed service without creating a runtime.
export const browserAnalyticsLayerAtom = Atom.make(
  Option.none<Layer.Layer<BrowserAnalytics>>(),
).pipe(Atom.keepAlive);
export const browserRuntime = Atom.runtime((get) => get(browserAppearanceLayerAtom));
// Decode remote configuration once without acquiring either remote service.
// Local appearance and progress do not depend on this Atom.
const checkedBrowserConfigAtom = browserRuntime
  .atom((get) =>
    get(browserConfigAtom).pipe(
      Effect.fromOption,
      Effect.mapError(() => new ApiConfigError({ reason: "unavailable" })),
      Effect.flatMap(Schema.decodeEffect(WebsiteBrowserConfig)),
    ),
  )
  .pipe(Atom.keepAlive);

export const browserApiTransportAtom = Atom.make(
  FetchHttpClient.layer.pipe(
    Layer.provide(
      Layer.succeed(FetchHttpClient.RequestInit, { credentials: "omit", redirect: "error" }),
    ),
  ),
).pipe(Atom.keepAlive);

// Native service construction owns the protocol and client; pages and tools share it.
export class ApiClient extends AtomHttpApi.Service<ApiClient>()(
  "common-practice/BrowserApiClient",
  {
    api: ContentApi,
    runtime: browserRuntime.factory,
    httpClient: (get) =>
      Layer.effect(
        HttpClient.HttpClient,
        HttpClient.HttpClient.pipe(
          Effect.map((client) =>
            client.pipe(
              HttpClient.mapRequestEffect((request) =>
                get.result(checkedBrowserConfigAtom, { suspendOnWaiting: true }).pipe(
                  Effect.map((config) => HttpClientRequest.prependUrl(request, config.apiOrigin)),
                  Effect.mapError(
                    (cause) =>
                      new HttpClientError.HttpClientError({
                        reason: new HttpClientError.InvalidUrlError({ request, cause }),
                      }),
                  ),
                ),
              ),
            ),
          ),
        ),
      ).pipe(Layer.provide(get(browserApiTransportAtom))),
  },
) {}
// Native retention keeps the connection available between route loads. The Layer
// cache also shares this service with any native query atom using ApiClient.runtime.
const apiClientRuntime = ApiClient.runtime.pipe(Atom.keepAlive);
export const browserApiClient = Atom.getResult(checkedBrowserConfigAtom, {
  suspendOnWaiting: true,
}).pipe(
  Effect.andThen(Atom.getResult(apiClientRuntime, { suspendOnWaiting: true })),
  Effect.map(Context.get(ApiClient)),
);

const BrowserToolHandlers = ContentTools.toLayer(
  Effect.gen(function* () {
    const client = yield* ApiClient;
    return ContentTools.of({
      list_pages: () =>
        client.pages.listPages({}).pipe(
          Effect.timeout(contentClientTimeout),
          Effect.map((pages) => ({ pages })),
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
            SchemaError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
            TimeoutError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
          }),
        ),
      get_page: (input) =>
        requestPage({ client, input }).pipe(
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
            SchemaError: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
            TimeoutError: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
          }),
        ),
      list_courses: () =>
        client.courses.listCourses({}).pipe(
          Effect.timeout(trainingClientTimeout),
          Effect.map((courses) => ({ courses })),
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "list-courses" })),
            SchemaError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "list-courses" })),
            TimeoutError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "list-courses" })),
          }),
        ),
      get_course: (input) =>
        requestCourse({ client, input }).pipe(
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "get-course" })),
            SchemaError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "get-course" })),
            TimeoutError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "get-course" })),
          }),
        ),
    });
  }),
);
// Analytics consumers share one client until the root registry closes. WebMCP
// registration never reads this Atom, so it does not initialise the SDK.
const analyticsServicesAtom = browserRuntime
  .atom((get) => {
    const analyticsLayer = get(browserAnalyticsLayerAtom);
    return Layer.build(
      Layer.unwrap(
        get
          .result(checkedBrowserConfigAtom, { suspendOnWaiting: true })
          .pipe(
            Effect.map((config) =>
              Option.getOrElse(analyticsLayer, () =>
                browserAnalyticsLayer
                  .pipe(Layer.provide(Layer.succeed(AnalyticsSettings, config.analytics)))
                  .pipe(
                    Layer.provide(Layer.succeed(WebsiteIdentity, { origin: config.websiteOrigin })),
                  ),
              ),
            ),
          ),
      ),
    );
  })
  .pipe(Atom.keepAlive);
export const withBrowserAnalytics = <A, E>(program: Effect.Effect<A, E, BrowserAnalytics>) =>
  Atom.getResult(analyticsServicesAtom, { suspendOnWaiting: true }).pipe(
    Effect.flatMap((services) => program.pipe(Effect.provide(services))),
  );

export const appearanceAtoms = makeAppearanceModel(browserRuntime);
export const appearanceControlAtom = browserRuntime
  .fn(
    Effect.fn("Browser.chooseAppearanceFromControl")(function* (input: AppearanceControlInput) {
      // Retain the scheduler yield so Atom tracks a child before input failure.
      yield* Effect.yieldNow;
      yield* appearanceAtoms.change(yield* readAppearanceControlInput(input));
    }),
    { concurrent: true },
  )
  .pipe(Atom.keepAlive);
export const webMcpAtom = browserRuntime.atom((get) =>
  Layer.build(
    Layer.unwrap(
      get
        .result(checkedBrowserConfigAtom, { suspendOnWaiting: true })
        .pipe(
          Effect.flatMap((config) =>
            get
              .result(apiClientRuntime, { suspendOnWaiting: true })
              .pipe(
                Effect.map((services) =>
                  Layer.mergeAll(
                    ModelContextHostLive.pipe(
                      Layer.provide(
                        Layer.succeed(WebsiteIdentity, { origin: config.websiteOrigin }),
                      ),
                    ),
                    BrowserToolHandlers.pipe(Layer.provide(Layer.succeedContext(services))),
                  ),
                ),
              ),
          ),
        ),
    ),
  ).pipe(Effect.flatMap((services) => registerWebMcpTools.pipe(Effect.provide(services)))),
);
export const pageViewAtom = browserRuntime.fn(
  Effect.fn("Browser.recordPageView")((input: PageView) =>
    Effect.gen(function* () {
      const analytics = yield* BrowserAnalytics;
      yield* analytics.recordPageView(input);
    }).pipe(withBrowserAnalytics),
  ),
  { concurrent: true },
);
export const navigationAtom = browserRuntime.fn(
  Effect.fn("Browser.recordNavigation")((input: NavigationUse) =>
    Effect.gen(function* () {
      const analytics = yield* BrowserAnalytics;
      yield* analytics.recordNavigation(input);
    }).pipe(withBrowserAnalytics),
  ),
  { concurrent: true },
);

// TanStack creates its router before loaders or React run. One registry is shared
// by those loaders and React's RegistryContext; there is no module-global state.
export const createLoaderRegistry = () => Option.some(AtomRegistry.make());

// TanStack's sole browser Promise bridge executes an Effect using this registry.
// Route results are owned by Router, so there is no request atom or second cache.
const runForLoader = <A, E>({
  effect,
  context,
  signal,
}: Readonly<{
  effect: Effect.Effect<A, E, AtomRegistry.AtomRegistry>;
  context: LoaderContext;
  signal: AbortSignal;
}>) =>
  Effect.runPromise(
    context.registry.pipe(
      Effect.fromOption,
      Effect.mapError(() => new ApiConfigError({ reason: "unavailable" })),
      Effect.flatMap((registry) =>
        effect.pipe(Effect.provideService(AtomRegistry.AtomRegistry, registry)),
      ),
    ),
    { signal },
  );

export const loadPage = (
  request: Readonly<{ input: PageInput; context: LoaderContext; signal: AbortSignal }>,
) =>
  runForLoader({
    effect: browserApiClient.pipe(
      Effect.flatMap((client) => readPage({ client, input: request.input })),
      Effect.catchCause(rejectRouteLoad),
    ),
    context: request.context,
    signal: request.signal,
  });
