export const readWebsiteConfig = Effect.gen(function* () {
  const registry = yield* AtomRegistry.AtomRegistry;
  const config = yield* Schema.decodeEffect(WebsiteConfig)(registry.get(websiteConfigAtom));
  return yield* Schema.encodeEffect(WebsiteConfig)({
    ...config,
    appearance: registry.get(appearanceAtoms.state).choice,
