// Request response adaptation stays at this one TanStack host boundary.
const rejectServerLoad = <E>(
  cause: Cause.Cause<E>,
): Effect.Effect<never, E | NotFoundError | WebsiteLoadError> => {
  if (Cause.hasInterruptsOnly(cause)) {
    return Effect.failCause(cause);
  }
  const status = loadFailureStatus(cause);
  return Effect.sync(() => {
    setResponseStatus(status);
  }).pipe(Effect.andThen(rejectRouteLoad(cause)));
};

const application = Layer.mergeAll(
  Logger.layer([Logger.consoleJson]),
  WebsiteApiLive,
  CaptureRelayLive.pipe(
    Layer.provide(
      FetchHttpClient.layer.pipe(
        Layer.provide(Layer.succeed(FetchHttpClient.RequestInit, { redirect: "manual" })),
      ),
    ),
  ),
  IsolateIdentityLive.pipe(Layer.provide(NodeCrypto.layer)),
);
type ApplicationServices = Layer.Success<typeof application>;

// TanStack owns this one frontend runtime. It supplies clients, never backend implementations.
const runtime = ManagedRuntime.make(application);
const runForRequest = <A, E>({
  effect,
  signal,
}: {
  readonly effect: Effect.Effect<A, E, ApplicationServices | ServerApiClient>;
  readonly signal?: AbortSignal;
}) => runtime.runPromise(effect.pipe(Effect.provide(ServerApiClientLive)), { signal });

export const handleCaptureRelayRequest = ({ request }: { readonly request: Request }) =>
  runForRequest({
    effect: captureRelayRequest.pipe(
      Effect.provideService(
        HttpServerRequest.HttpServerRequest,
        HttpServerRequest.fromWeb(request),
      ),
      Effect.map((response) =>
        HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD" }),
      ),
    ),
    signal: request.signal,
  });

export const handleMachineRequest = ({ request }: { readonly request: Request }) =>
  runForRequest({
    effect: WebsiteApi.pipe(
      Effect.flatMap((api) => api.forward(HttpServerRequest.fromWeb(request))),
      Effect.catchTag("ApiBindingError", () =>
        Effect.succeed(
          applyResponsePolicy({
            request: { adapter: "machine", method: request.method, pathname: Option.none() },
            response: HttpServerResponse.empty({ status: 503 }),
          }),
        ),
      ),
      Effect.map((response) =>
        HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD" }),
      ),
    ),
    signal: request.signal,
  });

export const handlePageRepresentation = ({ request }: { readonly request: Request }) =>
