              adapter: "machine",
              method: request.method,
              pathname: Url.fromString(request.url).pipe(
                Result.getSuccess,
                Option.map((url) => url.pathname),
              ),
            },
            response,
          }),
          { withoutBody: request.method === "HEAD" },
        ),
      ),
    ),
    signal: request.signal,
  });

