export const loadWebsiteConfig = ({
  request,
  signal,
}: {
  readonly request: Request;
  readonly signal: AbortSignal;
}) =>
  runForRequest({
    effect: Effect.gen(function* () {
      const header = yield* Effect.sync(() => request.headers.get("cookie") ?? "").pipe(
        Effect.flatMap(readAppearanceCookieHeader),
      );
      const appearance = yield* readAppearanceCookie(header, appearanceOptions);
      return yield* WebsiteApi.pipe(
        Effect.flatMap((api) => api.configuration),
        Effect.matchEffect({
          onSuccess: (origins) =>
            Schema.encodeEffect(WebsiteConfig)(
              WebsiteConfig.cases.WebsiteConfigured.make({ ...origins, appearance }),
            ),
          onFailure: () =>
            Schema.encodeEffect(WebsiteConfig)(
              WebsiteConfig.cases.WebsiteUnavailable.make({ appearance }),
            ),
        }),
      );
    }),
    signal: AbortSignal.any([request.signal, signal]),
  });

