export const publishingMiddleware = createMiddleware().server(
  ({ request, next: continueRequest }) =>
    runForRequest({
      effect: Effect.gen(function* () {
        const policyRequest: ResponsePolicyRequest = {
          adapter: "page",
          method: request.method,
          pathname: Url.fromString(request.url).pipe(
            Result.getSuccess,
            Option.map((url) => url.pathname),
          ),
          indexable: yield* WebsiteApi.pipe(
            Effect.flatMap((api) => api.stage),
            Effect.map((stage) => stage === "production"),
            Effect.orElseSucceed(() => false),
          ),
        };
        const selected = yield* discoveryRepresentation.pipe(
          Effect.flatMap((discovery) =>
            Option.match(discovery, {
              onNone: () => trainingRepresentation,
              onSome: Effect.succeedSome,
            }),
          ),
          Effect.flatMap((training) =>
            Option.match(training, {
              onNone: () => negotiatePage,
              onSome: Effect.succeedSome,
            }),
          ),
          Effect.provideService(
            HttpServerRequest.HttpServerRequest,
            HttpServerRequest.fromWeb(request),
          ),
        );
        if (Option.isSome(selected)) {
          return HttpServerResponse.toWeb(
            applyResponsePolicy({ request: policyRequest, response: selected.value }),
            { withoutBody: request.method === "HEAD" },
          );
        }
        // TanStack permits either a synchronous result or a Promise. tryPromise also
        // captures a synchronous throw from the framework callback.
        const result = yield* Effect.tryPromise({
          try: () => Promise.resolve(continueRequest()),
          catch: () => new HostAdapterError({ operation: "framework" }),
        });
        // Preserve the site's explicit 400/404/503 response status after Router
        // renders its native not-found or error component.
        const requestedStatus = yield* Effect.sync(getResponseStatus);
        const status = Match.value(requestedStatus).pipe(
          Match.when(200, () => result.response.status),
          Match.orElse((value) => value),
        );
        const appearanceHeader = yield* Effect.sync(() => request.headers.get("cookie") ?? "").pipe(
          Effect.flatMap(readAppearanceCookieHeader),
        );
        const savedAppearance = yield* readSavedAppearanceCookie(
          appearanceHeader,
          appearanceOptions,
        );
        const policy = responsePolicyHeaders({
          ...policyRequest,
          privateResponse:
            hasAppearanceCookie(appearanceHeader, appearanceOptions) &&
            Option.isNone(savedAppearance),
          varyCookie: true,
          status,
          headers: Headers.fromInput(result.response.headers),
          cookies: Cookies.empty,
        });
        // TanStack tracks the original response stream for SSR cleanup. Preserve its body
        // identity here; wrapping it in an Effect Stream would make TanStack close it early.
        return yield* Effect.try({
          try: () => {
            const headers = new globalThis.Headers(result.response.headers);
            Function.pipe(
              Record.toEntries(policy),
              Array.forEach(([name, value]) => {
                headers.set(name, value);
              }),
            );
            return {
              ...result,
              response: new Response(result.response.body, {
                status,
                statusText: result.response.statusText,
                headers,
              }),
            };
          },
          catch: () => new HostAdapterError({ operation: "framework" }),
        });
      }).pipe(observeWebsiteRequest(request)),
      signal: request.signal,
    }),
);
import type { WebsiteEnv } from "@common-practice/web/build/cloudflare";
import * as Effect from "effect/Effect";
import { pipe } from "effect/Function";
import * as Layer from "effect/Layer";
import * as Predicate from "effect/Predicate";
import * as Schema from "effect/Schema";
import { fromCloudflareFetcher, toHttpClient } from "alchemy/Cloudflare/Bridge";
import { ContentApi } from "@common-practice/http/api";
import * as HttpApiClient from "effect/http-api/HttpApiClient";
import * as Context from "effect/Context";
import * as Result from "effect/Result";
import { WebsiteApi } from "./service";
import { WebsiteAppConfig } from "../config";
import * as HttpClient from "effect/http/HttpClient";
import type * as HttpServerRequest from "effect/http/HttpServerRequest";
import { ApiBindingError } from "./errors";
import type * as ConfigProvider from "effect/ConfigProvider";
import type { WebsiteHttpClient } from "./requests";

const ApiBindingMethods = Schema.Struct({
  fetch: Schema.declare(Predicate.isFunction),
  connect: Schema.declare(Predicate.isFunction),
});

// Alchemy has no Schema for this opaque host object. Check the methods its
// bridge needs without copying the binding, so fetch retains its own receiver.
export const ApiBinding = Schema.declare<WebsiteEnv["BACKEND"]>(
  (binding): binding is WebsiteEnv["BACKEND"] => Schema.is(ApiBindingMethods)(binding),
);
export const forwardApiRequest = (
  request: HttpServerRequest.HttpServerRequest,
  binding: typeof ApiBinding.Type,
) =>
  Effect.suspend(() =>
    pipe(binding, fromCloudflareFetcher, (fetcher) => fetcher.fetch(request)),
  ).pipe(
    // Alchemy reports rejected host Promises as defects. Keep the Website's
    // named transport failure without turning interruption into a response.
    Effect.catchDefect(() => Effect.fail(new ApiBindingError({ operation: "forward" }))),
    Effect.mapError(() => new ApiBindingError({ operation: "forward" })),
  );

export const readWebsiteConfiguration = Effect.fn("WebsiteApi.configuration")(
  (provider: ConfigProvider.ConfigProvider) => WebsiteAppConfig.parse(provider),
  Effect.mapError(() => new ApiBindingError({ operation: "binding" })),
);

export class ServerApiClient extends Context.Service<
  ServerApiClient,
  Result.Result<WebsiteHttpClient, ApiBindingError>
>()("common-practice/ServerApiClient") {}

// A checked binding failure stays local to remote reads; it cannot prevent the
// root settings/appearance loader from using this single server runtime.
export const ServerApiClientLive = Layer.effect(
  ServerApiClient,
  HttpApiClient.make(ContentApi, { baseUrl: "https://backend" }).pipe(Effect.map(Result.succeed)),
).pipe(
  Layer.provide(
    Layer.unwrap(
      WebsiteApi.pipe(
        Effect.flatMap((api) => api.binding),
        Effect.map((binding) =>
          Layer.succeed(HttpClient.HttpClient, pipe(binding, fromCloudflareFetcher, toHttpClient)),
        ),
      ),
    ),
  ),
  // oxlint-disable-next-line promise/prefer-await-to-callbacks -- Native Layer failure composition is an Effect callback, not a Promise workflow.
  Layer.catchTag("ApiBindingError", (error) => Layer.succeed(ServerApiClient, Result.fail(error))),
);

